88	    const arg = args[i];
89	    if (arg === "-p" || arg === "--port") {
90	      const next = args[i + 1];
91	      if (next === undefined || next.startsWith("-")) {
92	        override = MISSING_PORT_VALUE;
93	        continue; // `next`, if any, is another flag — do not consume it as a value
94	      }
95	      override = next;
96	      i += 1;
97	      continue;
98	    }
99	    if (arg.startsWith("--port=")) {
100	      override = arg.slice("--port=".length);
