152	// exits unexpectedly before it can forward a shutdown signal. A no-op (and
153	// harmless) when run standalone, e.g. via `pnpm start`, where no IPC
154	// channel exists and `process.send` is undefined.
155	if (typeof process.send === "function" && child.pid !== undefined) {
156	  process.send({ type: "descendant-pid", pid: child.pid });
157	}
