159	// Forward a shutdown signal to the Next child and WAIT for it to actually
160	// exit before this wrapper exits — killing this wrapper alone must never
161	// leave Next running as an orphan. Bounded with an escalation to SIGKILL
162	// if Next does not exit within the grace period (an uncooperative or
163	// stuck child must not hang the wrapper, or whatever is supervising it,
164	// forever).
165	const SHUTDOWN_GRACE_MS = 5000;
166	let shuttingDown = false;
167	let escalationTimer;
