181	process.on("SIGINT", () => forwardShutdown("SIGINT"));
182	process.on("SIGTERM", () => forwardShutdown("SIGTERM"));
183	
184	child.on("exit", (code, signal) => {
185	  clearTimeout(escalationTimer);
186	  if (signal) {
187	    process.kill(process.pid, signal);
188	    return;
189	  }
190	  process.exit(code ?? 1);
191	});
