1	import { existsSync, readFileSync } from "node:fs";
2	import path from "node:path";
3	import dotenv from "dotenv";
4	import { ConfigValidationError } from "./errors.js";
5	
6	/**
7	 * Server-only: loads dotenv files before an entry point reads
8	 * process.env. Never import this from public.ts or web browser code.
9	 */
10	
11	export type RuntimeMode = "development" | "test" | "production";
12	
13	// Matches $VAR / ${VAR}, with a leading backslash escaping the whole
14	// reference to a literal "$VAR" / "${VAR}" (dotenv-expand convention).
15	const EXPANSION_PATTERN = /(\\)?\$\{([A-Za-z_][A-Za-z0-9_]*)\}|(\\)?\$([A-Za-z_][A-Za-z0-9_]*)/g;
16	
17	/**
18	 * Finds the pnpm workspace root by walking up from `startDir` looking for
19	 * pnpm-workspace.yaml. Falls back to `startDir` itself if none is found
20	 * (e.g. a package checked out standalone).
21	 */
22	export function findWorkspaceRoot(startDir: string): string {
23	  let dir = path.resolve(startDir);
24	  for (;;) {
25	    if (existsSync(path.join(dir, "pnpm-workspace.yaml"))) return dir;
26	    const parent = path.dirname(dir);
27	    if (parent === dir) return path.resolve(startDir);
28	    dir = parent;
29	  }
30	}
31	
32	function candidateFiles(mode: RuntimeMode, cwd: string): string[] {
33	  const root = findWorkspaceRoot(cwd);
34	  const resolvedCwd = path.resolve(cwd);
35	  const directories = resolvedCwd === root ? [resolvedCwd] : [resolvedCwd, root];
36	
37	  // Matches installed Next.js behavior: .env.test.local IS loaded in test
38	  // mode (only the generic .env.local is skipped there, since tests should
39	  // produce the same results for everyone regardless of a developer's
40	  // local overrides).
41	  const tiers = [
42	    `.env.${mode}.local`,
43	    mode !== "test" ? ".env.local" : null,
44	    `.env.${mode}`,
45	    ".env",
46	  ].filter((file): file is string => file !== null);
47	
48	  const files: string[] = [];
49	  const seen = new Set<string>();
50	  for (const tier of tiers) {
51	    for (const dir of directories) {
52	      const filePath = path.join(dir, tier);
53	      if (seen.has(filePath)) continue;
54	      seen.add(filePath);
55	      files.push(filePath);
56	    }
57	  }
58	  return files;
59	}
60	
61	/**
62	 * Determines the winning RAW (unexpanded) value per key across every
63	 * candidate file, in precedence order (highest first): for each
64	 * Next.js-style tier — .env.<mode>.local > .env.local (skipped in test
65	 * mode only) > .env.<mode> > .env — the package directory's file wins over
66	 * the workspace root's file at that same tier. First match per key wins;
67	 * later files never override an earlier winner.
68	 */
69	function collectWinners(mode: RuntimeMode, cwd: string): Record<string, string> {
70	  const winners: Record<string, string> = {};
71	  for (const filePath of candidateFiles(mode, cwd)) {
72	    if (!existsSync(filePath)) continue;
73	    const parsed = dotenv.parse(readFileSync(filePath, "utf8"));
74	    for (const [key, value] of Object.entries(parsed)) {
75	      if (!(key in winners)) winners[key] = value;
76	    }
77	  }
78	  return winners;
79	}
80	
81	/**
82	 * Resolves `name`'s fully-expanded value, deterministically, regardless of
83	 * where in `winners` it happens to be declared:
84	 *  - An already-resolved base/OS value always wins outright and is
85	 *    returned as-is (base values are never templates to re-expand).
86	 *  - A winner's raw value is expanded on demand, recursively resolving any
87	 *    reference it contains first (memoized in `resolved`), so a chain like
88	 *    C=${B}, B=${A}, A=resolved converges to the same result regardless of
89	 *    declaration order.
90	 *  - A reference to a name that is neither a base value nor a winner
91	 *    expands to an empty string (documented unresolved-reference
92	 *    behavior).
93	 *  - A direct or indirect cycle (name re-entered while already being
94	 *    resolved) throws a safe ConfigValidationError — naming only the
95	 *    variable, never a value — instead of recursing forever or returning a
96	 *    partially-expanded string.
97	 */
98	function resolveValue(
99	  name: string,
100	  winners: Record<string, string>,
101	  base: Record<string, string>,
102	  resolved: Map<string, string>,
103	  inProgress: Set<string>,
104	): string {
105	  const baseValue = base[name];
106	  if (baseValue !== undefined) return baseValue;
107	
108	  const cached = resolved.get(name);
109	  if (cached !== undefined) return cached;
110	
111	  const raw = winners[name];
112	  if (raw === undefined) return "";
113	
114	  if (inProgress.has(name)) {
115	    throw new ConfigValidationError("env", [{ variable: name, category: "runtime" }]);
116	  }
117	  inProgress.add(name);
118	
119	  const expanded = raw.replace(
120	    EXPANSION_PATTERN,
121	    (
122	      match,
123	      escapedBraced: string | undefined,
124	      bracedName: string | undefined,
125	      escapedBare: string | undefined,
126	      bareName: string | undefined,
127	    ) => {
128	      if (escapedBraced || escapedBare) return match.slice(1);
129	      const referenced = bracedName ?? bareName ?? "";
130	      return resolveValue(referenced, winners, base, resolved, inProgress);
131	    },
132	  );
133	
134	  inProgress.delete(name);
135	  resolved.set(name, expanded);
136	  return expanded;
137	}
138	
139	/**
140	 * Pure computation of an application's fully resolved effective
141	 * environment: `baseEnv` (typically the real OS environment, or a
