607	  const { apiEnv, webEnv, workerEnv, databaseEnv } = validation;
608	
609	  const steps = [];
610	  if (!skipMigrate) {
611	    // databaseEnv was already resolved (root/package env-file precedence)
612	    // AND validated above — including its CONTROL_DATABASE_URL and its
613	    // NODE_ENV forced to the same `mode` — so it is passed through
614	    // unchanged. Raw process.env is never re-read here.
615	    steps.push(createMigrateStep("control", databaseEnv));
616	  }
617	  if (!skipBuild) {
618	    steps.push(createBuildStep("api", ["--filter", "./apps/api", "build"], apiEnv));
619	    steps.push(createBuildStep("worker", ["--filter", "@relis/worker", "build"], workerEnv));
620	    steps.push(createBuildStep("web", ["--filter", "./apps/web", "build"], webEnv));
621	  }
622	  if (!skipWorker) {
623	    steps.push(createWorkerStep(workerEnv));
624	  }
625	
626	  const stepResult = await runSteps(steps);
627	  if (!stepResult.ok) {
628	    console.error(JSON.stringify({ code: "DEPLOY_STEP_FAILED", step: stepResult.failedStep }));
629	    process.exit(stepResult.exitCode);
630	  }
631	
632	  // Only api and web are genuinely long-running; see the module docstring
633	  // for why apps/worker is a completing step above instead.
634	  const services = [
635	    { name: "api", command: process.execPath, args: [path.join(apiDir, "dist", "main.js")], env: apiEnv, cwd: apiDir },
636	    {
637	      name: "web",
638	      command: process.execPath,
639	      args: [path.join(webDir, "scripts", "run.mjs"), "start"],
640	      env: webEnv,
641	      cwd: webDir,
642	    },
643	  ];
644	
645	  const supervisor = startAndSupervise(services);
646	  process.on("SIGINT", () => supervisor.requestShutdown("SIGINT"));
647	  process.on("SIGTERM", () => supervisor.requestShutdown("SIGTERM"));
648	
649	  const exitCode = await supervisor.exitPromise;
