1	import { execFileSync, spawn, type ChildProcessWithoutNullStreams, type SpawnOptions } from "node:child_process";
2	
3	// On Windows, spawning with shell:true runs the command inside a cmd.exe
4	// wrapper; killing that wrapper process does NOT kill the real process it
5	// launched (e.g. node/next), leaking a listener that outlives the test.
6	// taskkill /T kills the whole process tree instead.
7	function killProcessTree(pid: number | undefined): void {
8	  if (pid === undefined) return;
9	  if (process.platform === "win32") {
10	    try {
11	      execFileSync("taskkill", ["/pid", String(pid), "/T", "/F"], { stdio: "ignore" });
12	    } catch {
13	      // Already exited.
14	    }
15	    return;
16	  }
17	  try {
18	    process.kill(pid, "SIGKILL");
19	  } catch {
20	    // Already exited.
21	  }
22	}
23	
24	function quoteArg(value: string): string {
25	  return /^[\w./:@-]+$/.test(value) ? value : JSON.stringify(value);
26	}
27	
28	// Builds a single shell command line instead of passing shell:true together
29	// with an argv array, which avoids Node's shell-argument-escaping
30	// deprecation warning (DEP0190). Test commands/args here are fixed
31	// literals or generated port numbers, never untrusted input.
32	function toShellCommand(command: string, args: string[]): string {
33	  return [command, ...args.map(quoteArg)].join(" ");
34	}
35	
36	export interface SpawnResult {
37	  exitCode: number | null;
38	  signal: NodeJS.Signals | null;
39	  stdout: string;
40	  stderr: string;
41	}
42	
43	/**
44	 * Runs a command to completion and captures its output. Intended for
45	 * processes that are expected to exit on their own (a failed startup
46	 * validation, a worker that logs and exits).
47	 */
48	export function runToCompletion(
49	  command: string,
50	  args: string[],
51	  options: SpawnOptions & { timeoutMs?: number } = {},
52	): Promise<SpawnResult> {
53	  const { timeoutMs = 30000, ...spawnOptions } = options;
54	
55	  return new Promise((resolve, reject) => {
56	    const child = spawn(toShellCommand(command, args), { ...spawnOptions, shell: true });
57	    let stdout = "";
58	    let stderr = "";
59	
60	    const timer = setTimeout(() => {
61	      killProcessTree(child.pid);
62	      reject(new Error(`Process timed out after ${timeoutMs}ms: ${command} ${args.join(" ")}`));
63	    }, timeoutMs);
64	
65	    child.stdout?.on("data", (chunk: Buffer) => {
66	      stdout += chunk.toString();
67	    });
68	    child.stderr?.on("data", (chunk: Buffer) => {
69	      stderr += chunk.toString();
70	    });
71	    child.on("error", (error) => {
72	      clearTimeout(timer);
73	      reject(error);
74	    });
75	    child.on("exit", (code, signal) => {
76	      clearTimeout(timer);
77	      resolve({ exitCode: code, signal, stdout, stderr });
78	    });
79	  });
80	}
81	
82	export interface LongRunningProcess {
83	  child: ChildProcessWithoutNullStreams;
84	  stdout: () => string;
85	  stderr: () => string;
86	  waitForOutput: (predicate: (combined: string) => boolean, timeoutMs?: number) => Promise<void>;
87	  stop: () => Promise<void>;
88	}
89	
90	/**
91	 * Spawns a process expected to keep running (a dev/start server) so a test
92	 * can assert on its output and then clean it up deterministically.
93	 */
94	export function spawnLongRunning(
95	  command: string,
96	  args: string[],
97	  options: SpawnOptions = {},
98	): LongRunningProcess {
99	  const child = spawn(toShellCommand(command, args), { ...options, shell: true }) as ChildProcessWithoutNullStreams;
100	  let stdout = "";
101	  let stderr = "";
102	
103	  child.stdout.on("data", (chunk: Buffer) => {
104	    stdout += chunk.toString();
105	  });
106	  child.stderr.on("data", (chunk: Buffer) => {
107	    stderr += chunk.toString();
108	  });
109	
110	  async function waitForOutput(predicate: (combined: string) => boolean, timeoutMs = 30000): Promise<void> {
111	    const start = Date.now();
112	    while (Date.now() - start < timeoutMs) {
113	      if (predicate(stdout + stderr)) return;
114	      if (child.exitCode !== null) {
115	        throw new Error(
116	          `Process exited (code ${child.exitCode}) before expected output.\nstdout=${stdout}\nstderr=${stderr}`,
117	        );
118	      }
119	      await new Promise((resolveDelay) => setTimeout(resolveDelay, 200));
120	    }
121	    throw new Error(`Timed out waiting for expected output.\nstdout=${stdout}\nstderr=${stderr}`);
