    if (stop.exitCode !== 0) {
      throw new Error(`docker compose stop postgres failed:\n${stop.stderr}`);
    }
  }, 300000);

  afterAll(async () => {
    await composeDown(project, { timeoutMs: 180000 });
  }, 180000);

  it("fails migrate-control (valid config, unreachable target) instead of silently succeeding", async () => {
    const result = await composeRun(
      project,
      "migrate-control",
      {},
      {
        command: ["sh", "-c", "pnpm --filter @relis/config build && pnpm --filter @relis/database run migrate control"],
        timeoutMs: 120000,
      },
    );

