  expect(health.status).toBe(200);
  const healthBody = (await health.json()) as { status: string };
  expect(healthBody.status).toBe("ok");

  const ready = await fetch(`http://127.0.0.1:${nginxPort}/api/ready`);
  expect(ready.status).toBe(200);
  const readyBody = (await ready.json()) as { status: string; checks: Record<string, string> };
  expect(readyBody.status).toBe("ok");
  // Matches apps/api/src/app.ts's actual, honest readiness contract: it
  // only reports network/cors, never a database/queue it does not have.
  expect(readyBody.checks).toEqual({ network: "ok", cors: "ok" });
});

it("serves the web app through the same proxy origin as the API (browser-public address)", async () => {
  const page = await fetch(`http://127.0.0.1:${nginxPort}/`);
  expect(page.status).toBe(200);
});

it("gives the frontend a real, browser-reachable NEXT_PUBLIC_API_URL whose API request actually succeeds through the proxy", async () => {
  // Fetching the page's HTML alone (the previous test) does not prove
  // the frontend's OWN configured API URL is correct or reachable —
  // Next dev serves an HTML shell regardless. Read the ACTUAL value
  // the running `web` container was given (ground truth, not an
  // assumption) and confirm it is the real nginx port, never the
  // ephemeral-port placeholder "0" that NGINX_HTTP_PORT=0 would
  // otherwise leak into it (see getFreePort's doc comment for why that
  // bug was possible and how choosing a real port before `up` avoids
