      const timer = setTimeout(() => {
        killProcessTree(pid);
        resolveStop();
      }, 5000);
      child.once("exit", () => {
        clearTimeout(timer);
        resolveStop();
      });
      killProcessTree(pid);
    });
  }

  return {
    child,
    stdout: () => stdout,
    stderr: () => stderr,
    waitForOutput,
    stop,
  };
}

